70	                    ((Number) p.get("clientId")).longValue());
71	        }
72	        List<Map<String, Object>> contacts =
73	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
74	        for (Map<String, Object> c : contacts) {
75	            jdbc.update(
76	                    "INSERT INTO contacts (id, name, email, contact_role, client_id)"
77	                            + " VALUES (?, ?, ?, ?, ?)",
78	                    ((Number) c.get("id")).longValue(), c.get("name"), c.get("email"),
79	                    c.get("role"), ((Number) c.get("clientId")).longValue());
80	        }
81	        List<Map<String, Object>> invoices =
82	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
83	        for (Map<String, Object> inv : invoices) {
84	            Object status = inv.getOrDefault("status", "DRAFT");
85	            // Dates are optional in the fixture — a spec that only cares about the lifecycle leaves
86	            // them out, so default issued=today / due=+30 days (the same rule CreateInvoice applies).
87	            java.time.LocalDate issued = inv.get("issuedDate") != null
88	                    ? java.time.LocalDate.parse(inv.get("issuedDate").toString())
89	                    : java.time.LocalDate.now();
90	            java.time.LocalDate due = inv.get("dueDate") != null
91	                    ? java.time.LocalDate.parse(inv.get("dueDate").toString())
92	                    : issued.plusDays(30);
93	            // An invoice is built from line items; its amount is the sum of each line's qty times
94	            // unit price. A fixture gives the lines (not a figure), so compute the amount from them
95	            // here — the same derivation CreateLineItem keeps in step on every add. A legacy fixture
96	            // that still supplies an explicit amount (and no lines) is honoured as-is.
97	            List<Map<String, Object>> lineItems =
98	                    (List<Map<String, Object>>) inv.getOrDefault("lineItems", List.of());
99	            java.math.BigDecimal amount;
100	            if (inv.get("amount") != null) {
101	                amount = new java.math.BigDecimal(inv.get("amount").toString());
102	            } else {
103	                amount = java.math.BigDecimal.ZERO;
104	                for (Map<String, Object> li : lineItems) {
105	                    amount = amount.add(new java.math.BigDecimal(li.get("unitPrice").toString())
106	                            .multiply(new java.math.BigDecimal(li.get("qty").toString())));
107	                }
108	            }
109	            jdbc.update(
110	                    "INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
111	                            + " VALUES (?, ?, ?, ?, ?, ?)",
112	                    ((Number) inv.get("id")).longValue(),
113	                    ((Number) inv.get("projectId")).longValue(),
114	                    amount,
115	                    status.toString(),
116	                    java.sql.Date.valueOf(issued),
117	                    java.sql.Date.valueOf(due));
118	            // Insert the invoice's lines with their explicit fixture ids (the spec asserts rows by
119	            // these ids), owned by this invoice.
120	            for (Map<String, Object> li : lineItems) {
121	                jdbc.update(
122	                        "INSERT INTO invoice_line_items"
123	                                + " (id, invoice_id, description, quantity, unit_price)"
124	                                + " VALUES (?, ?, ?, ?, ?)",
125	                        ((Number) li.get("id")).longValue(),
126	                        ((Number) inv.get("id")).longValue(),
127	                        li.get("description"),
128	                        ((Number) li.get("qty")).intValue(),
129	                        new java.math.BigDecimal(li.get("unitPrice").toString()));
130	            }
131	        }
132	        // Payments a client has made against an invoice (amount + the date paid), with their
133	        // explicit fixture ids (the spec asserts rows by these ids), owned by a seeded invoice.
134	        List<Map<String, Object>> payments =
135	                (List<Map<String, Object>>) fixture.getOrDefault("payments", List.of());
136	        long maxPaymentId = 0;
137	        for (Map<String, Object> pay : payments) {
138	            long paymentId = ((Number) pay.get("id")).longValue();
139	            jdbc.update(
140	                    "INSERT INTO invoice_payments (id, invoice_id, amount, paid_date)"
141	                            + " VALUES (?, ?, ?, ?)",
142	                    paymentId,
143	                    ((Number) pay.get("invoiceId")).longValue(),
144	                    new java.math.BigDecimal(pay.get("amount").toString()),
145	                    java.sql.Date.valueOf(
146	                            java.time.LocalDate.parse(pay.get("date").toString())));
147	            maxPaymentId = Math.max(maxPaymentId, paymentId);
148	        }
149	        // Explicit ids (GENERATED BY DEFAULT) do NOT advance H2's identity sequence, so a payment
150	        // recorded through the API would collide on id 1. Bump the sequence past the seeded rows.
151	        if (maxPaymentId > 0) {
152	            jdbc.execute(
153	                    "ALTER TABLE invoice_payments ALTER COLUMN id RESTART WITH " + (maxPaymentId + 1));
154	        }
155	        List<Map<String, Object>> tasks =
156	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
157	        for (Map<String, Object> t : tasks) {
158	            // done is optional in the fixture — a spec that only cares a task exists leaves it out,
