160	            boolean done = Boolean.TRUE.equals(t.getOrDefault("done", Boolean.FALSE));
161	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
162	                    ((Number) t.get("id")).longValue(),
163	                    ((Number) t.get("projectId")).longValue(),
164	                    t.get("title"), done);
165	        }
166	        List<Map<String, Object>> tags =
167	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
168	        for (Map<String, Object> tag : tags) {
169	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)",
170	                    ((Number) tag.get("id")).longValue(), tag.get("name"));
171	        }
172	        // Notes are written against a generic target (type + id); the fixture pins each note's
173	        // write time so the newest-first order is deterministic. `at` is optional — a spec that
174	        // only cares a note exists leaves it out, defaulting to now().
175	        List<Map<String, Object>> notes =
176	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
177	        long maxNoteId = 0;
178	        for (Map<String, Object> n : notes) {
179	            java.time.OffsetDateTime at = n.get("at") != null
180	                    ? java.time.OffsetDateTime.parse(n.get("at").toString())
181	                    : java.time.OffsetDateTime.now();
182	            long noteId = ((Number) n.get("id")).longValue();
183	            jdbc.update(
184	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
185	                            + " VALUES (?, ?, ?, ?, ?)",
186	                    noteId,
187	                    n.get("targetType"),
188	                    ((Number) n.get("targetId")).longValue(),
189	                    n.get("text"),
190	                    at);
