194	        // next create would collide on id 1. Bump the sequence past the seeded rows so a note added
195	        // through the API gets a fresh id above them.
196	        if (maxNoteId > 0) {
197	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
198	        }
199	        // The many-to-many links: which seeded tag sits on which seeded project.
200	        List<Map<String, Object>> projectTags =
201	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
202	        for (Map<String, Object> pt : projectTags) {
203	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
204	                    ((Number) pt.get("projectId")).longValue(),
205	                    ((Number) pt.get("tagId")).longValue());
206	        }
207	    }
208	}
