16	            ProjectRepository projects, ClientRepository clients,
17	            ObjectResponse<List<ProjectView>> response) {
18	        Long id = Long.valueOf(clientId);
19	        String clientName = clients.findById(id).map(Client::getName).orElse("");
20	        // Archived projects are tucked away — they drop off the client's list too, keeping the row
21	        // in the table only while it is active.
22	        List<ProjectView> view = projects.findByClientIdOrderByIdAsc(id).stream()
23	                .filter(p -> !p.isArchived())
24	                .map(p -> ProjectView.of(p, clientName))
25	                .toList();
26	        response.send(view);
27	    }
28	}
